import { cn } from "@/lib/utils"

/** Green Control spinner: a square-cornered ring that inherits the text colour. */
export function Spinner({ className }: { className?: string }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        "inline-block size-3 shrink-0 animate-spin rounded-full border-[1.5px] border-current/30 border-t-current motion-reduce:animate-none",
        className
      )}
    />
  )
}
